//! The step-through debug session (issue #667, R383).
//!
//! `serve --debug-session` binds loopback only, every debug request needs the
//! session token, a paused turn advances one stage per authenticated advance (a
//! repeated or stale advance answers 409 and records nothing), and a release or
//! a client disconnect never leaves a solve paused. Every stage event carries
//! the turn's recipe as Mermaid source with the stage highlighted, the
//! `path:symbol` locations, lines and excerpts of the code that emits that
//! stage in both runtimes (`rust/src/server/debug_stage_sources.rs` over the
//! generated `data/meta/debug-stage-sources.lino`), and the method-registry
//! method the turn's route resolves to with its handlers
//! (`rust/src/server/debug_stage.rs`); a held turn is neither persisted nor
//! answered. The JavaScript twin is
//! `rust/tests/web/server-debug-session.test.mjs`; the protocol is
//! `docs/vscode/debugger.md`.

use std::time::Duration;

use formal_ai::derivation::{answer_derivation_id, store_path};
use formal_ai::server::{
    DebugSession, DebugToken, EXCERPT_LINES, StageView, TurnView, debug_session_banner,
    describe_turn, enable_debug_session, handle_debug_request, is_loopback_host, stage_diagram,
    with_connection_scope,
};
use formal_ai::{ApiAuthConfig, ApiHttpResponse, ThinkingStep, handle_api_request_with_auth};
use serde_json::{Value, json};

const TOKEN: &str = "debug-session-test-token";
const BEARER: &str = "debug-session-bearer";
const SOLVE_ENTRY: &str =
    "rust/src/solver.rs:solve_with_history_probability_store_and_intent_cache";
const EVENT_LOG: &str = "js/worker/formal_ai_worker_solver_events.js:solverEventLog";
const ARITHMETIC: &str = "rust/src/solver_handlers/mod.rs:try_arithmetic";
const CALCULATION_EVENTS: &str =
    "js/worker/formal_ai_worker_solver_events.js:solverCalculationEvents";
const FINALIZE: &str = "rust/src/solver_handlers/mod.rs:finalize_simple";
const INTENT_RECORD: (&str, &str) = (
    "rust/src/intent_formalization.rs:record_intent_formalization",
    "js/agentic/crate/intent_formalization.mjs:recordIntentFormalization",
);

/// Every stage of the served `What is 2 + 2?` turn: `(step, Rust emitter, JS emitter)`.
const TWO_PLUS_TWO: [(&str, &str, &str); 10] = [
    ("impulse", SOLVE_ENTRY, EVENT_LOG),
    ("detect_language", SOLVE_ENTRY, EVENT_LOG),
    ("formalize", INTENT_RECORD.0, INTENT_RECORD.1),
    ("compute", ARITHMETIC, CALCULATION_EVENTS),
    ("compute_engine", ARITHMETIC, CALCULATION_EVENTS),
    ("compute_expression", ARITHMETIC, CALCULATION_EVENTS),
    ("compute_steps", ARITHMETIC, CALCULATION_EVENTS),
    ("dispatch_handler", FINALIZE, EVENT_LOG),
    // The browser solverEventLog emits the real validation event.
    ("rule_verification", FINALIZE, EVENT_LOG),
    ("deformalize", FINALIZE, EVENT_LOG),
];

fn session() -> DebugSession {
    DebugSession::new(DebugToken {
        token: TOKEN.to_owned(),
        generated: false,
    })
}

fn stages() -> Vec<ThinkingStep> {
    vec![
        ThinkingStep::new(0, "impulse", "What is 2 + 2?", "high", "impulse"),
        ThinkingStep::new(1, "compute", "4", "high", "calculation"),
        ThinkingStep::new(2, "deformalize", "4", "high", "response"),
    ]
}

/// A turn routed to `arithmetic`, with a sub-stage under `compute`.
fn routed() -> Vec<ThinkingStep> {
    let compute = ThinkingStep::new(2, "compute", "2 + 2 = 4", "high", "calculation");
    let engine = ThinkingStep::new(
        3,
        "compute_engine",
        "link-calculator",
        "high",
        "calculation:engine",
    )
    .with_parent(compute.id.clone());
    vec![
        ThinkingStep::new(0, "impulse", "What is 2 + 2?", "high", "impulse"),
        ThinkingStep::new(
            1,
            "formalize",
            "arithmetic",
            "high",
            "intent_formalization:route",
        ),
        compute,
        engine,
        ThinkingStep::new(4, "deformalize", "2 + 2 = 4", "high", "response"),
    ]
}

/// The repository the test runs in (`rust/` is the working directory).
fn repository() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("..")
}

/// The located excerpt is the file's own text from the definition line on.
///
/// A method's definition line is indented inside its `impl` block (the solve
/// entry `solve_with_history_probability_store_and_intent_cache` is one), so
/// the indentation is trimmed before the visibility, as the JavaScript twin's
/// unanchored `fn <symbol>(` pattern does.
fn assert_excerpt(source: &str, line: u64, excerpt: &str, definition: &str) {
    let file = source.rsplit_once(':').map_or(source, |(file, _)| file);
    let text = std::fs::read_to_string(repository().join(file)).expect("located file");
    let lines: Vec<&str> = text.split('\n').collect();
    let shown: Vec<&str> = excerpt.split('\n').collect();
    let start = usize::try_from(line).expect("line") - 1;
    assert!(
        lines[start]
            .trim_start()
            .trim_start_matches("pub(crate) ")
            .trim_start_matches("pub ")
            .trim_start_matches("export ")
            .starts_with(definition),
        "{}",
        lines[start]
    );
    assert_eq!(shown, lines[start..start + shown.len()]);
    assert!(shown.len() <= EXCERPT_LINES, "an excerpt is capped");
}

/// The text of a string field of an event, empty when absent.
fn text<'event>(event: &'event Value, field: &str) -> &'event str {
    event[field].as_str().unwrap_or("")
}

/// Every stage names its own emitters, located in the files they live in, and
/// the routed method stays a separate field (empty while nothing is routed).
fn assert_stage_sources(events: &[&Value], expected: &[(&str, &str, &str)]) {
    let named: Vec<(&str, &str, &str)> = events
        .iter()
        .map(|event| {
            (
                text(event, "step"),
                text(event, "rust_source"),
                text(event, "js_source"),
            )
        })
        .collect();
    assert_eq!(named, expected);
    for event in events {
        for (runtime, keyword) in [("rust", "fn "), ("js", "function ")] {
            let source = text(event, &format!("{runtime}_source"));
            let symbol = source.rsplit_once(':').map_or("", |(_, symbol)| symbol);
            let line = event[format!("{runtime}_line")].as_u64().unwrap_or(0);
            let excerpt = text(event, &format!("{runtime}_excerpt"));
            assert_excerpt(source, line, excerpt, &format!("{keyword}{symbol}"));
        }
        let routed = text(event, "method") == "arithmetic";
        assert!(routed || text(event, "method").is_empty());
        assert_eq!(
            text(event, "method_rust_source"),
            if routed {
                "rust/src/solver_dispatch.rs:handle_arithmetic"
            } else {
                ""
            }
        );
        assert_eq!(
            text(event, "method_js_source"),
            if routed {
                "js/worker/formal_ai_worker_arithmetic_and_numeric_lists.js:tryArithmetic"
            } else {
                ""
            }
        );
    }
}

fn kinds(snapshot: &Value) -> Vec<String> {
    snapshot["events"]
        .as_array()
        .expect("events")
        .iter()
        .map(|event| {
            format!(
                "{}:{}",
                event["kind"].as_str().unwrap_or(""),
                event["stage"]
            )
        })
        .collect()
}

/// Poll until a turn is paused, and return the paused entry.
fn paused_turn(session: &DebugSession) -> Value {
    for _ in 0..600 {
        let snapshot = session.snapshot(None);
        if let Some(paused) = snapshot["paused"]
            .as_array()
            .and_then(|paused| paused.first())
        {
            return paused.clone();
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    panic!("no turn paused");
}

fn error_message(response: &ApiHttpResponse) -> String {
    let body: Value = serde_json::from_str(&response.body).expect("json error body");
    body["error"]["message"].as_str().unwrap_or("").to_owned()
}

#[test]
fn only_loopback_hosts_may_carry_a_debug_session() {
    for host in [
        "127.0.0.1",
        "127.1.2.3",
        "localhost",
        "LOCALHOST",
        "::1",
        "[::1]",
    ] {
        assert!(is_loopback_host(host), "{host}");
    }
    for host in [
        "0.0.0.0",
        "192.168.1.5",
        "::",
        "example.com",
        "128.0.0.1",
        "127.0.0.256",
        "",
    ] {
        assert!(!is_loopback_host(host), "{host}");
    }
    assert_eq!(
        enable_debug_session("0.0.0.0").map(|_| ()),
        Err(String::from("debug_session_requires_loopback:0.0.0.0"))
    );
}

#[test]
fn the_banner_prints_only_a_generated_token() {
    let given = session();
    assert_eq!(
        debug_session_banner(&given),
        format!("debug_session={}", given.id())
    );
    assert!(given.id().starts_with("debug_session_"));
    let generated = DebugSession::new(DebugToken {
        token: String::from("abc"),
        generated: true,
    });
    assert_eq!(
        debug_session_banner(&generated),
        format!("debug_session={};token=abc", generated.id())
    );
    let fresh = formal_ai::server::generate_debug_token();
    assert_eq!(fresh.len(), 48);
    assert!(fresh.bytes().all(|byte| byte.is_ascii_hexdigit()));
    assert_ne!(fresh, formal_ai::server::generate_debug_token());
    assert!(given.authorizes(TOKEN));
    assert!(!given.authorizes("debug-session-test-tokem"));
    assert!(!given.authorizes(""));
}

#[test]
fn stepping_off_never_holds_a_turn() {
    let session = session();
    session.gate(&stages(), &mut || true);
    assert_eq!(kinds(&session.snapshot(None)), Vec::<String>::new());
}

#[test]
fn each_advance_reveals_exactly_one_stage_and_a_repeat_records_nothing() {
    let session = session();
    session.pause();
    let stages = stages();
    std::thread::scope(|scope| {
        let held = scope.spawn(|| session.gate(&stages, &mut || true));
        let paused = paused_turn(&session);
        assert_eq!(paused["turn"], "turn_1");
        assert_eq!(paused["stage"], 0);
        assert!(!session.advance("turn_1", Some(1)), "stage 1 is not paused");
        assert!(!session.advance("turn_9", Some(0)), "an unknown turn");
        assert!(
            !session.advance("turn_1", None),
            "an advance names its stage"
        );
        assert!(session.advance("turn_1", Some(0)));
        assert!(!session.advance("turn_1", Some(0)), "stage 0 was advanced");
        assert!(session.advance("turn_1", Some(1)));
        assert!(!held.is_finished(), "held at the last stage");
        assert!(session.advance("turn_1", Some(2)));
        held.join().expect("the turn completes");
    });
    let snapshot = session.snapshot(None);
    assert_eq!(
        kinds(&snapshot),
        [
            "stage_paused:0",
            "stage_advanced:0",
            "stage_paused:1",
            "stage_advanced:1",
            "stage_paused:2",
            "stage_advanced:2",
            "turn_released:2",
        ]
    );
    let three_stage_diagram = [
        "flowchart TD",
        "    s0[\"0 impulse\"]",
        "    s1[\"1 compute\"]",
        "    s2[\"2 deformalize\"]",
        "    s0 --> s1",
        "    s1 --> s2",
        "    classDef current stroke-width:4px",
        "    class s1 current",
    ]
    .join("\n");
    // No route: no method. The JavaScript `calculation` event has one
    // appender, so it is the emitter; the Rust one has several and none is
    // reached from the solver entry, so it records no location.
    let mut paused = snapshot["events"][2].clone();
    assert_eq!(text(&paused, "js_source"), CALCULATION_EVENTS);
    assert_excerpt(
        CALCULATION_EVENTS,
        paused["js_line"].as_u64().unwrap_or(0),
        text(&paused, "js_excerpt"),
        "function solverCalculationEvents(",
    );
    if let Some(fields) = paused.as_object_mut() {
        for field in ["js_excerpt", "js_line", "js_source"] {
            fields.remove(field);
        }
    }
    assert_eq!(
        paused,
        json!({
            "detail": "4", "id": "debug_event_3", "kind": "stage_paused", "method": "",
            "method_js_excerpt": "", "method_js_line": 0, "method_js_source": "",
            "method_rust_excerpt": "", "method_rust_line": 0, "method_rust_source": "",
            "mermaid": three_stage_diagram,
            "rust_excerpt": "", "rust_line": 0, "rust_source": "",
            "session": session.id(), "source": "calculation", "stage": 1,
            "stages": 3, "step": "compute", "turn": "turn_1",
        })
    );
    assert_eq!(snapshot["events"][6]["reason"], "completed");
    assert_eq!(snapshot["next"], 7);
    assert_eq!(
        session.snapshot(Some(6))["events"],
        json!([snapshot["events"][6].clone()])
    );
    assert!(!session.advance("turn_1", Some(2)), "a released turn");
}

#[test]
fn every_stage_carries_the_recipe_diagram_its_own_emitters_and_the_routed_method() {
    let session = session();
    session.pause();
    let stages = routed();
    std::thread::scope(|scope| {
        let held = scope.spawn(|| session.gate(&stages, &mut || true));
        paused_turn(&session);
        for stage in 0..3 {
            assert!(session.advance("turn_1", Some(stage)));
        }
        let paused = session.snapshot(None)["paused"][0].clone();
        assert_eq!(paused["stage"], 3);
        assert_eq!(paused["method"], "arithmetic");
        assert_eq!(
            paused["mermaid"],
            [
                "flowchart TD",
                "    s0[\"0 impulse\"]",
                "    s1[\"1 formalize\"]",
                "    s2[\"2 compute\"]",
                "    s3[\"3 compute_engine\"]",
                "    s4[\"4 deformalize\"]",
                "    s0 --> s1",
                "    s1 --> s2",
                "    s2 -.-> s3",
                "    s2 --> s4",
                "    classDef current stroke-width:4px",
                "    class s3 current",
            ]
            .join("\n")
        );
        let rust = text(&paused, "method_rust_source");
        let js = text(&paused, "method_js_source");
        assert_eq!(rust, "rust/src/solver_dispatch.rs:handle_arithmetic");
        assert_eq!(
            js,
            "js/worker/formal_ai_worker_arithmetic_and_numeric_lists.js:tryArithmetic"
        );
        let excerpt = text(&paused, "method_rust_excerpt");
        assert_excerpt(
            rust,
            paused["method_rust_line"].as_u64().unwrap_or(0),
            excerpt,
            "fn handle_arithmetic(",
        );
        assert_eq!(
            excerpt.rsplit('\n').next(),
            Some("}"),
            "runs to the closing brace"
        );
        assert_excerpt(
            js,
            paused["method_js_line"].as_u64().unwrap_or(0),
            text(&paused, "method_js_excerpt"),
            "function tryArithmetic(",
        );
        session.release(None);
        held.join().expect("the release frees the turn");
    });
    // Each stage names the code that emits it; the highlight moves with it.
    let events = session.snapshot(None)["events"].clone();
    let paused_events: Vec<&Value> = events
        .as_array()
        .expect("events")
        .iter()
        .filter(|event| event["kind"] == "stage_paused")
        .collect();
    assert_stage_sources(
        &paused_events,
        &[
            ("impulse", SOLVE_ENTRY, EVENT_LOG),
            ("formalize", INTENT_RECORD.0, INTENT_RECORD.1),
            ("compute", ARITHMETIC, CALCULATION_EVENTS),
            ("compute_engine", ARITHMETIC, CALCULATION_EVENTS),
        ],
    );
    let highlighted: Vec<&str> = paused_events
        .iter()
        .map(|event| text(event, "mermaid").rsplit('\n').next().unwrap_or(""))
        .collect();
    assert_eq!(
        highlighted,
        [
            "    class s0 current",
            "    class s1 current",
            "    class s2 current",
            "    class s3 current",
        ]
    );
    // A rule-set method resolves to the rule interpreter in both runtimes; a
    // route the registry does not know records no method, and a stage whose
    // event no function appends records no location at all.
    let rule = describe_turn(&[ThinkingStep::new(
        0,
        "formalize",
        "clarification",
        "high",
        "route",
    )]);
    let rule_rust = rule.rust.expect("rule interpreter");
    let rule_js = rule.js.expect("browser rule handler");
    assert_eq!(
        format!("{}:{}", rule_rust.path, rule_rust.symbol),
        "rust/src/rule_interpreter.rs:run_handler"
    );
    assert_eq!(
        format!("{}:{}", rule_js.path, rule_js.symbol),
        "js/worker/formal_ai_worker_handler_rules.js:tryClarification"
    );
    let unknown = describe_turn(&[ThinkingStep::new(
        0,
        "formalize",
        "greeting",
        "high",
        "no_such_event",
    )]);
    assert_eq!(
        unknown,
        TurnView {
            stages: vec![StageView::default()],
            ..TurnView::default()
        }
    );
    let quoted = stage_diagram(&[ThinkingStep::new(0, "say \"hi\"", "", "high", "x")], 0);
    assert_eq!(
        quoted.split('\n').nth(1),
        Some("    s0[\"0 say #quot;hi#quot;\"]")
    );
}

#[test]
fn a_turn_begun_before_its_solve_waits_at_its_first_stage_then_resumes() {
    let session = session();
    let stages = stages();
    assert_eq!(
        session.begin(&stages[0], &mut || true),
        None,
        "stepping off never opens a turn"
    );
    session.pause();
    std::thread::scope(|scope| {
        let opening = scope.spawn(|| session.begin(&stages[0], &mut || true));
        let paused = paused_turn(&session);
        assert_eq!(
            [
                &paused["turn"],
                &paused["stage"],
                &paused["stages"],
                &paused["step"]
            ],
            [&json!("turn_1"), &json!(0), &json!(1), &json!("impulse")]
        );
        assert!(
            !opening.is_finished(),
            "the solve waits until stage 0 is advanced"
        );
        assert!(session.advance("turn_1", Some(0)));
        let begun = opening.join().expect("the advance lets the solve run");
        assert_eq!(begun.as_deref(), Some("turn_1"));
        assert_eq!(
            session.snapshot(None)["paused"],
            json!([]),
            "a running solve has no paused stage"
        );
        assert!(!session.advance("turn_1", Some(0)), "stage 0 was advanced");
        assert!(
            !session.advance("turn_1", Some(1)),
            "stage 1 is not computed yet"
        );
        let resumed = scope.spawn(|| session.resume("turn_1", &stages, &mut || true));
        let paused = paused_turn(&session);
        assert_eq!(
            [&paused["stage"], &paused["stages"]],
            [&json!(1), &json!(3)]
        );
        assert!(session.advance("turn_1", Some(1)));
        assert!(session.advance("turn_1", Some(2)));
        resumed.join().expect("the turn completes");
    });
    let snapshot = session.snapshot(None);
    assert_eq!(
        kinds(&snapshot),
        [
            "stage_paused:0",
            "stage_advanced:0",
            "stage_paused:1",
            "stage_advanced:1",
            "stage_paused:2",
            "stage_advanced:2",
            "turn_released:2",
        ]
    );
    assert_eq!(snapshot["events"][6]["reason"], "completed");
    // A turn released while its solve runs is not held again.
    std::thread::scope(|scope| {
        let opening = scope.spawn(|| session.begin(&stages[0], &mut || true));
        paused_turn(&session);
        assert!(session.advance("turn_2", Some(0)));
        let running = opening
            .join()
            .expect("the solve runs")
            .expect("an open turn");
        session.release(Some(running.as_str()));
        session.resume(&running, &stages, &mut || true);
    });
    let snapshot = session.snapshot(None);
    let events = snapshot["events"].as_array().expect("events");
    assert_eq!(
        events.last().map(|event| &event["reason"]),
        Some(&json!("released"))
    );
    assert_eq!(snapshot["paused"], json!([]));
}

#[test]
fn a_disconnect_or_a_release_frees_a_paused_turn() {
    let session = session();
    session.pause();
    let stages = stages();
    session.gate(&stages, &mut || false);
    let snapshot = session.snapshot(None);
    assert_eq!(snapshot["events"][1]["kind"], "turn_released");
    assert_eq!(snapshot["events"][1]["reason"], "disconnected");
    std::thread::scope(|scope| {
        let held = scope.spawn(|| session.gate(&stages, &mut || true));
        let paused = paused_turn(&session);
        assert_eq!(paused["turn"], "turn_2");
        session.release(None);
        held.join().expect("the release frees the turn");
    });
    let snapshot = session.snapshot(None);
    assert_eq!(snapshot["stepping"], false);
    assert_eq!(snapshot["paused"], json!([]));
    assert_eq!(snapshot["events"][3]["reason"], "released");
}

#[test]
fn debug_requests_answer_the_twin_errors() {
    let disabled = handle_debug_request(None, "session", "{}");
    assert_eq!(disabled.status_code, 404);
    assert_eq!(error_message(&disabled), "debug_session_disabled");
    let session = session();
    let malformed = handle_debug_request(Some(&session), "session", "{not json");
    assert_eq!(malformed.status_code, 400);
    assert_eq!(error_message(&malformed), "debug_request_invalid");
    for action in ["session", "pause", "advance", "release"] {
        let refused = handle_debug_request(Some(&session), action, r#"{"token":"wrong"}"#);
        assert_eq!(refused.status_code, 401, "{action}");
        assert_eq!(error_message(&refused), "debug_session_token_invalid");
    }
    let rejected_advance = handle_debug_request(
        Some(&session),
        "advance",
        &json!({ "token": TOKEN, "turn": "turn_1", "stage": 0 }).to_string(),
    );
    assert_eq!(rejected_advance.status_code, 409);
    assert_eq!(error_message(&rejected_advance), "debug_stage_not_paused");
    let state = handle_debug_request(
        Some(&session),
        "pause",
        &json!({ "token": TOKEN }).to_string(),
    );
    assert_eq!(state.status_code, 200);
    let body: Value = serde_json::from_str(&state.body).expect("snapshot");
    assert_eq!(
        body,
        json!({
            "events": [], "next": 0, "object": "debug.session", "paused": [],
            "session": session.id(), "stepping": true,
        })
    );
}

/// The served route, end to end: a chat turn solved inside a connection scope
/// is held until its last stage is advanced through `POST /v1/debug/advance`.
#[test]
fn a_served_chat_turn_answers_only_after_its_last_stage() {
    let dir = std::env::temp_dir().join(format!("formal-ai-debug-session-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("temp dir");
    let memory = dir.join("memory.lino");
    let dialogs = dir.join("dialogs");
    temp_env::with_vars(
        [
            ("FORMAL_AI_MEMORY_PATH", Some(memory.as_os_str())),
            ("FORMAL_AI_DIALOG_LOG_DIR", Some(dialogs.as_os_str())),
            ("FORMAL_AI_RECORD_CHAT", Some(std::ffi::OsStr::new("0"))),
            (
                "FORMAL_AI_DEBUG_SESSION_TOKEN",
                Some(std::ffi::OsStr::new(TOKEN)),
            ),
        ],
        || {
            let session = enable_debug_session("127.0.0.1").expect("loopback");
            let auth = ApiAuthConfig::bearer_token(BEARER);
            let bearer = format!("Bearer {BEARER}");
            let headers = [("authorization", bearer.as_str())];
            let debug = |action: &str, body: &Value| {
                handle_api_request_with_auth(
                    "POST",
                    &format!("/v1/debug/{action}"),
                    &headers,
                    &body.to_string(),
                    &auth,
                )
            };
            // The record the turn's answer is persisted under, removed so the
            // held turn can be seen not to write it.
            let root = std::env::current_dir().expect("working directory");
            let record = store_path(&root, &formal_ai::solve("What is 2 + 2?").derivation_id())
                .expect("record path");
            let _ = std::fs::remove_file(&record);
            assert_eq!(debug("pause", &json!({ "token": TOKEN })).status_code, 200);
            let chat = json!({
                "model": "formal-ai",
                "messages": [{ "role": "user", "content": "What is 2 + 2?" }],
            })
            .to_string();
            std::thread::scope(|scope| {
                let answered = scope.spawn(|| {
                    with_connection_scope(
                        || true,
                        || {
                            handle_api_request_with_auth(
                                "POST",
                                "/v1/chat/completions",
                                &headers,
                                &chat,
                                &auth,
                            )
                        },
                    )
                });
                // Stage 0 is truly suspended: only the prompt is known, the
                // solver has not run, so nothing is routed yet.
                let mut paused = paused_turn(session);
                assert_eq!(
                    [
                        &paused["stage"],
                        &paused["stages"],
                        &paused["step"],
                        &paused["method"]
                    ],
                    [&json!(0), &json!(1), &json!("impulse"), &json!("")]
                );
                let first = json!({ "token": TOKEN, "turn": paused["turn"], "stage": 0 });
                assert_eq!(debug("advance", &first).status_code, 200);
                assert_eq!(debug("advance", &first).status_code, 409);
                // Stages 1.. are revealed from the solved turn, held before it
                // is persisted.
                paused = paused_turn(session);
                let total = paused["stages"].as_u64().expect("stage count");
                assert_eq!(total, TWO_PLUS_TWO.len() as u64);
                assert_eq!(paused["method"], "arithmetic");
                assert_eq!(
                    paused["method_rust_source"],
                    "rust/src/solver_dispatch.rs:handle_arithmetic"
                );
                for stage in 1..total {
                    assert_eq!(paused["stage"], stage);
                    assert!(!answered.is_finished(), "held before stage {stage}");
                    assert!(
                        !record.exists(),
                        "not persisted while stage {stage} is held"
                    );
                    assert!(
                        paused["mermaid"]
                            .as_str()
                            .is_some_and(|mermaid| mermaid
                                .ends_with(&format!("\n    class s{stage} current"))),
                        "stage {stage} is highlighted"
                    );
                    let request = json!({ "token": TOKEN, "turn": paused["turn"], "stage": stage });
                    let advanced = debug("advance", &request);
                    assert_eq!(advanced.status_code, 200);
                    let repeated = debug("advance", &request);
                    assert_eq!(repeated.status_code, 409, "a stage is never advanced twice");
                    if stage + 1 < total {
                        let body: Value = serde_json::from_str(&advanced.body).expect("snapshot");
                        paused = body["paused"][0].clone();
                    }
                }
                // Stepping off before the join: a second solve inside the same
                // request (a restated standing requirement) is never held.
                let released = debug("release", &json!({ "token": TOKEN }));
                let state: Value = serde_json::from_str(&released.body).expect("snapshot");
                assert_eq!(state["stepping"], false);
                let response = answered.join().expect("the turn answers");
                assert_eq!(response.status_code, 200);
                let body: Value = serde_json::from_str(&response.body).expect("completion");
                let content = body["choices"][0]["message"]["content"]
                    .as_str()
                    .unwrap_or("");
                assert!(content.contains('4'));
                assert_eq!(
                    store_path(&root, &answer_derivation_id(content)).as_ref(),
                    Some(&record),
                    "the served answer is the one whose record was removed"
                );
                assert!(record.exists(), "the release persists the record");
            });
            let state = debug("session", &json!({ "token": TOKEN }));
            let snapshot: Value = serde_json::from_str(&state.body).expect("snapshot");
            let advanced: Vec<&Value> = snapshot["events"]
                .as_array()
                .expect("events")
                .iter()
                .filter(|event| event["kind"] == "stage_advanced")
                .collect();
            assert_stage_sources(&advanced, &TWO_PLUS_TWO);
            let counts: Vec<u64> = advanced
                .iter()
                .map(|event| event["stages"].as_u64().unwrap_or(0))
                .collect();
            let mut expected = vec![TWO_PLUS_TWO.len() as u64; TWO_PLUS_TWO.len()];
            expected[0] = 1;
            assert_eq!(
                counts, expected,
                "stage 0 was paused before the turn was solved"
            );
        },
    );
    let _ = std::fs::remove_dir_all(&dir);
}

// The step-through debug session of the JavaScript server (issue #667, R383,
// js/server/debug-session.mjs; protocol in docs/vscode/debugger.md): the
// `--debug-session` flag binds loopback only, every debug request needs the
// session token, a paused turn advances one stage per authenticated advance
// (a repeated or stale advance answers 409 and records nothing), and release
// or a client disconnect never leaves a solve paused. Every stage event carries
// the turn's recipe as Mermaid source with the stage highlighted, the
// `path:symbol` locations, lines and excerpts of the code that emits that stage
// in both runtimes (js/server/debug-stage-sources.mjs over the generated
// data/meta/debug-stage-sources.lino), and the method-registry method the
// turn's route resolves to with its handlers (js/server/debug-stage.mjs); a
// held turn is neither persisted nor answered. The Rust twin is
// rust/tests/unit/specification/debug_session.rs.

import assert from "node:assert/strict";
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { after, before, describe, test } from "node:test";

import { answerDerivationId } from "../../../js/agentic/crate/derivation.mjs";
import { hasHost, installHost } from "../../../js/agentic/host.mjs";
import { DebugSession, debugSessionBanner, debugTokenFrom, isLoopbackHost } from "../../../js/server/debug-session.mjs";
import { describeTurn, stageDiagram } from "../../../js/server/debug-stage.mjs";
import { STAGE_SOURCES } from "../../../js/server/debug-stage-sources.mjs";
import { renderStageSources } from "../../../scripts/generate-debug-stage-sources.mjs";
import { REPO_ROOT, parseLino, readRepoFile } from "../../../js/server/lino.mjs";
import { parseArgs, startServer } from "../../../js/server/main.mjs";

const TOKEN = "debug-session-test-token";
const STAGES = [
  { step: "impulse", detail: "What is 2 + 2?", source_event: "impulse" },
  { step: "compute", detail: "4", source_event: "calculation" },
  { step: "deformalize", detail: "4", source_event: "response" },
];

// A turn routed to `arithmetic`, with a sub-stage under `compute`.
const ROUTED = [
  { id: "step_0", step: "impulse", detail: "What is 2 + 2?", source_event: "impulse" },
  { id: "step_1", step: "formalize", detail: "arithmetic", source_event: "intent_formalization:route" },
  { id: "step_2", step: "compute", detail: "2 + 2 = 4", source_event: "calculation" },
  { id: "step_3", step: "compute_engine", detail: "link-calculator", source_event: "calculation:engine", parent_id: "step_2" },
  { id: "step_4", step: "deformalize", detail: "2 + 2 = 4", source_event: "response" },
];

const NO_LOCATION = {
  method: "", js_excerpt: "", js_line: 0, js_source: "", rust_excerpt: "", rust_line: 0, rust_source: "",
  method_js_excerpt: "", method_js_line: 0, method_js_source: "",
  method_rust_excerpt: "", method_rust_line: 0, method_rust_source: "",
};

const SOLVE_ENTRY = "rust/src/solver.rs:solve_with_history_probability_store_and_intent_cache";
const EVENT_LOG = "js/worker/formal_ai_worker_solver_events.js:solverEventLog";
const ARITHMETIC = "rust/src/solver_handlers/mod.rs:try_arithmetic";
const CALCULATION_EVENTS = "js/worker/formal_ai_worker_solver_events.js:solverCalculationEvents";
const FINALIZE = "rust/src/solver_handlers/mod.rs:finalize_simple";
const INTENT_RECORD = ["rust/src/intent_formalization.rs:record_intent_formalization",
  "js/agentic/crate/intent_formalization.mjs:recordIntentFormalization"];

// Every stage of the served `What is 2 + 2?` turn: `[step, Rust emitter, JS emitter]`.
const TWO_PLUS_TWO = [
  ["impulse", SOLVE_ENTRY, EVENT_LOG],
  ["detect_language", SOLVE_ENTRY, EVENT_LOG],
  ["formalize", ...INTENT_RECORD],
  ["compute", ARITHMETIC, CALCULATION_EVENTS],
  ["compute_engine", ARITHMETIC, CALCULATION_EVENTS],
  ["compute_expression", ARITHMETIC, CALCULATION_EVENTS],
  ["compute_steps", ARITHMETIC, CALCULATION_EVENTS],
  ["dispatch_handler", FINALIZE, EVENT_LOG],
  ["rule_verification", FINALIZE, EVENT_LOG],
  ["deformalize", FINALIZE, EVENT_LOG],
];

/**
 * Every stage names its own emitters, located in the files they live in, and
 * the routed method stays a separate field (empty while nothing is routed).
 */
function assertStageSources(events, expected) {
  assert.deepEqual(events.map((event) => [event.step, event.rust_source, event.js_source]), expected);
  for (const event of events) {
    assertExcerpt(event.rust_source, event.rust_line, event.rust_excerpt, new RegExp(`fn ${event.rust_source.split(":")[1]}[(<]`));
    assertExcerpt(event.js_source, event.js_line, event.js_excerpt, new RegExp(`function ${event.js_source.split(":")[1]}\\(`));
    const routed = event.method === "arithmetic";
    assert.ok(routed || event.method === "", event.method);
    assert.equal(event.method_rust_source, routed ? "rust/src/solver_dispatch.rs:handle_arithmetic" : "");
    assert.equal(event.method_js_source, routed ? "js/worker/formal_ai_worker_arithmetic_and_numeric_lists.js:tryArithmetic" : "");
  }
}

/** The located excerpt is the file's own text from the definition line on. */
function assertExcerpt(source, line, excerpt, definition) {
  const file = source.slice(0, source.lastIndexOf(":"));
  const lines = readFileSync(path.join(REPO_ROOT, file), "utf8").split("\n");
  const shown = excerpt.split("\n");
  assert.match(lines[line - 1], definition);
  assert.deepEqual(shown, lines.slice(line - 1, line - 1 + shown.length));
  assert.ok(shown.length <= 40, "an excerpt is capped at 40 lines");
}

const kinds = (session) => session.events.map((event) => `${event.kind}:${event.stage}`);

describe("the session state machine (DebugSession)", () => {
  test("only loopback hosts may carry a debug session", () => {
    for (const host of ["127.0.0.1", "127.1.2.3", "localhost", "LOCALHOST", "::1", "[::1]"]) {
      assert.equal(isLoopbackHost(host), true, host);
    }
    for (const host of ["0.0.0.0", "192.168.1.5", "::", "example.com", "128.0.0.1", "127.0.0.256", ""]) {
      assert.equal(isLoopbackHost(host), false, host);
    }
  });

  test("the token comes from the launcher, else it is generated and printed once", () => {
    const given = debugTokenFrom({ FORMAL_AI_DEBUG_SESSION_TOKEN: ` ${TOKEN} ` });
    assert.deepEqual(given, { token: TOKEN, generated: false });
    const session = new DebugSession(given);
    assert.equal(debugSessionBanner(session), `debug_session=${session.id}`);
    const generated = debugTokenFrom({});
    assert.equal(generated.generated, true);
    assert.match(generated.token, /^[0-9a-f]{48}$/);
    const fresh = new DebugSession(generated);
    assert.equal(debugSessionBanner(fresh), `debug_session=${fresh.id};token=${generated.token}`);
    assert.ok(fresh.authorizes(generated.token));
    assert.ok(!fresh.authorizes(TOKEN));
    assert.ok(!fresh.authorizes(undefined));
  });

  test("stepping off never holds a turn", async () => {
    const session = new DebugSession(TOKEN);
    await session.gate(STAGES);
    assert.deepEqual(session.events, []);
  });

  test("each advance reveals exactly one stage and a repeated advance records nothing", async () => {
    const session = new DebugSession(TOKEN);
    session.pause();
    let finished = false;
    const held = session.gate(STAGES).then(() => {
      finished = true;
    });
    assert.deepEqual(kinds(session), ["stage_paused:0"]);
    assert.equal(session.advance("turn_1", 1), false, "stage 1 is not the paused stage");
    assert.equal(session.advance("turn_9", 0), false, "an unknown turn");
    assert.equal(session.advance("turn_1", 0), true);
    assert.equal(session.advance("turn_1", 0), false, "stage 0 was already advanced");
    assert.deepEqual(kinds(session), ["stage_paused:0", "stage_advanced:0", "stage_paused:1"]);
    assert.equal(session.advance("turn_1", 1), true);
    await new Promise((resolve) => setImmediate(resolve));
    assert.equal(finished, false, "the turn is still held at its last stage");
    assert.equal(session.advance("turn_1", 2), true);
    await held;
    assert.deepEqual(kinds(session), [
      "stage_paused:0", "stage_advanced:0", "stage_paused:1", "stage_advanced:1",
      "stage_paused:2", "stage_advanced:2", "turn_released:2",
    ]);
    const last = session.events.at(-1);
    assert.equal(last.reason, "completed");
    assert.equal(last.session, session.id);
    assert.equal(last.turn, "turn_1");
    assert.equal(session.advance("turn_1", 2), false, "a released turn never advances");
    // No route: no method. The JavaScript `calculation` event has one
    // appender, so it is the emitter; the Rust one has several and none is
    // reached from the solver entry, so it records no location.
    const { js_excerpt: excerpt, js_line: line, js_source: source, ...paused } = session.events[2];
    assert.equal(source, CALCULATION_EVENTS);
    assertExcerpt(source, line, excerpt, /^function solverCalculationEvents\(/);
    const { js_excerpt: _excerpt, js_line: _line, js_source: _source, ...noLocation } = NO_LOCATION;
    assert.deepEqual(paused, {
      ...noLocation,
      detail: "4", id: "debug_event_3", kind: "stage_paused", session: session.id,
      mermaid: [
        "flowchart TD",
        '    s0["0 impulse"]',
        '    s1["1 compute"]',
        '    s2["2 deformalize"]',
        "    s0 --> s1",
        "    s1 --> s2",
        "    classDef current stroke-width:4px",
        "    class s1 current",
      ].join("\n"),
      source: "calculation", stage: 1, stages: 3, step: "compute", turn: "turn_1",
    });
    assert.deepEqual(session.snapshot(6).events.map((event) => event.id), ["debug_event_7"]);
  });

  test("every stage carries the recipe diagram, its own emitters and the routed method", async () => {
    if (!hasHost()) installHost({ readText: readRepoFile, parseLino });
    const session = new DebugSession(TOKEN);
    session.pause();
    const held = session.gate(ROUTED);
    for (let stage = 0; stage < 3; stage += 1) assert.equal(session.advance("turn_1", stage), true);
    const paused = session.snapshot().paused[0];
    assert.equal(paused.stage, 3);
    assert.equal(paused.method, "arithmetic");
    assert.equal(paused.mermaid, [
      "flowchart TD",
      '    s0["0 impulse"]',
      '    s1["1 formalize"]',
      '    s2["2 compute"]',
      '    s3["3 compute_engine"]',
      '    s4["4 deformalize"]',
      "    s0 --> s1",
      "    s1 --> s2",
      "    s2 -.-> s3",
      "    s2 --> s4",
      "    classDef current stroke-width:4px",
      "    class s3 current",
    ].join("\n"));
    assert.equal(paused.method_rust_source, "rust/src/solver_dispatch.rs:handle_arithmetic");
    assert.equal(paused.method_js_source, "js/worker/formal_ai_worker_arithmetic_and_numeric_lists.js:tryArithmetic");
    assertExcerpt(paused.method_rust_source, paused.method_rust_line, paused.method_rust_excerpt, /^fn handle_arithmetic\(/);
    assertExcerpt(paused.method_js_source, paused.method_js_line, paused.method_js_excerpt, /^function tryArithmetic\(/);
    assert.equal(paused.method_rust_excerpt.split("\n").at(-1), "}", "the excerpt runs to the closing brace");
    session.release();
    await held;
    // Each stage names the code that emits it; the highlight moves with it.
    const staged = session.events.filter((event) => event.kind === "stage_paused");
    assertStageSources(staged, [
      ["impulse", SOLVE_ENTRY, EVENT_LOG],
      ["formalize", ...INTENT_RECORD],
      ["compute", ARITHMETIC, CALCULATION_EVENTS],
      ["compute_engine", ARITHMETIC, CALCULATION_EVENTS],
    ]);
    assert.deepEqual(staged.map((event) => event.mermaid.split("\n").at(-1)),
      ["    class s0 current", "    class s1 current", "    class s2 current", "    class s3 current"]);
    // A rule-set method resolves to the rule interpreter in both runtimes; a
    // route the registry does not know records no method, and a stage whose
    // event no function appends records no location at all.
    const rule = describeTurn([{ step: "formalize", detail: "clarification" }]);
    assert.equal(`${rule.rust.path}:${rule.rust.symbol}`, "rust/src/rule_interpreter.rs:run_handler");
    assert.equal(`${rule.js.path}:${rule.js.symbol}`, "js/worker/formal_ai_worker_handler_rules.js:tryClarification");
    assert.deepEqual(describeTurn([{ step: "formalize", detail: "greeting", source_event: "no_such_event" }]),
      { method: "", rust: null, js: null, stages: [{ rust: null, js: null }] });
    assert.equal(stageDiagram([{ step: 'say "hi"' }], 0).split("\n")[1], '    s0["0 say #quot;hi#quot;"]');
  });

  test("the stage-sources table is current with the source tree", () => {
    assert.equal(readFileSync(path.join(REPO_ROOT, STAGE_SOURCES), "utf8"), renderStageSources(),
      "run node scripts/generate-debug-stage-sources.mjs --write");
  });

  test("a turn begun before its solve waits at its first stage, then resumes", async () => {
    const session = new DebugSession(TOKEN);
    assert.equal(await session.begin(STAGES[0]), null, "stepping off never opens a turn");
    session.pause();
    let begun = null;
    const opening = session.begin(STAGES[0]).then((turn) => {
      begun = turn;
    });
    const paused = session.snapshot().paused[0];
    assert.deepEqual([paused.turn, paused.stage, paused.stages, paused.step], ["turn_1", 0, 1, "impulse"]);
    await new Promise((resolve) => setImmediate(resolve));
    assert.equal(begun, null, "the solve waits until stage 0 is advanced");
    assert.equal(session.advance("turn_1", 0), true);
    await opening;
    assert.equal(begun.running, true);
    assert.deepEqual(session.snapshot().paused, [], "a running solve has no paused stage");
    assert.equal(session.advance("turn_1", 0), false, "stage 0 was advanced");
    assert.equal(session.advance("turn_1", 1), false, "stage 1 is not computed yet");
    const resumed = session.resume(begun, STAGES);
    assert.equal(session.snapshot().paused[0].stage, 1);
    assert.equal(session.snapshot().paused[0].stages, 3);
    assert.equal(session.advance("turn_1", 1), true);
    assert.equal(session.advance("turn_1", 2), true);
    await resumed;
    assert.deepEqual(kinds(session), [
      "stage_paused:0", "stage_advanced:0", "stage_paused:1", "stage_advanced:1",
      "stage_paused:2", "stage_advanced:2", "turn_released:2",
    ]);
    assert.equal(session.events.at(-1).reason, "completed");
    // A turn released while its solve runs is not held again.
    const second = session.begin(STAGES[0]);
    session.advance("turn_2", 0);
    const running = await second;
    session.release("turn_2");
    await session.resume(running, STAGES);
    assert.equal(session.events.at(-1).reason, "released");
    assert.deepEqual(session.snapshot().paused, []);
  });

  test("a disconnect or a release frees a paused turn", async () => {
    const session = new DebugSession(TOKEN);
    session.pause();
    const disconnect = new AbortController();
    const first = session.gate(STAGES, disconnect.signal);
    disconnect.abort();
    await first;
    assert.equal(session.events.at(-1).reason, "disconnected");
    const second = session.gate(STAGES);
    assert.equal(session.snapshot().paused.length, 1);
    session.release();
    await second;
    assert.equal(session.events.at(-1).reason, "released");
    assert.equal(session.stepping, false, "a release without a turn stops stepping");
    assert.deepEqual(session.snapshot().paused, []);
  });
});

describe("the --debug-session server", () => {
  let server;
  let base;
  let home;
  let ctx;

  before(async () => {
    home = mkdtempSync(path.join(os.tmpdir(), "formal-ai-debug-session-"));
    const env = {
      ...process.env,
      HOME: home,
      FORMAL_AI_MEMORY_PATH: path.join(home, "memory.lino"),
      FORMAL_AI_DIALOG_LOG_DIR: path.join(home, "dialogs"),
      FORMAL_AI_RECORD_CHAT: "0",
      FORMAL_AI_DEBUG_SESSION_TOKEN: TOKEN,
    };
    delete env.FORMAL_AI_API_BEARER_TOKEN;
    delete env.FORMAL_AI_HTTP_BEARER_TOKEN;
    delete env.FORMAL_AI_API_TOKEN;
    ({ server, url: base, ctx } = await startServer({ port: 0, env, debugSession: true }));
    ctx.derivationRoot = home;
  });

  after(() => {
    server?.close();
    if (home) rmSync(home, { recursive: true, force: true });
  });

  async function debug(action, body) {
    const response = await fetch(`${base}/v1/debug/${action}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(body),
    });
    return { status: response.status, body: JSON.parse(await response.text()) };
  }

  function chat(signal) {
    return fetch(`${base}/v1/chat/completions`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ model: "formal-ai", messages: [{ role: "user", content: "What is 2 + 2?" }] }),
      signal,
    });
  }

  async function pausedTurn() {
    for (let attempt = 0; attempt < 600; attempt += 1) {
      const { body } = await debug("session", { token: TOKEN });
      if (body.paused.length) return body.paused[0];
      await new Promise((resolve) => setTimeout(resolve, 50));
    }
    throw new Error("no turn paused");
  }

  test("the flag parses, and a non-loopback bind is refused", async () => {
    assert.equal(parseArgs(["serve", "--debug-session"], {}).debugSession, true);
    assert.equal(parseArgs(["serve"], {}).debugSession, false);
    await assert.rejects(startServer({ host: "0.0.0.0", port: 0, debugSession: true }), /^Error: debug_session_requires_loopback:0\.0\.0\.0$/);
  });

  test("every debug request needs the session token", async () => {
    for (const action of ["session", "pause", "advance", "release"]) {
      const refused = await debug(action, { token: "wrong" });
      assert.equal(refused.status, 401, action);
      assert.equal(refused.body.error.message, "debug_session_token_invalid");
    }
    const malformed = await fetch(`${base}/v1/debug/session`, { method: "POST", body: "{not json" });
    assert.equal(malformed.status, 400);
    const state = await debug("session", { token: TOKEN });
    assert.equal(state.status, 200);
    assert.equal(state.body.object, "debug.session");
    assert.equal(state.body.stepping, false);
  });

  test("a paused chat turn waits before it is solved and answers only after its last stage", async () => {
    assert.equal((await debug("pause", { token: TOKEN })).body.stepping, true);
    const before = (await debug("session", { token: TOKEN })).body.next;
    const solve = ctx.worker.solve.bind(ctx.worker);
    let solves = 0;
    ctx.worker.solve = (...args) => {
      solves += 1;
      return solve(...args);
    };
    let answered = false;
    const pending = chat().then(async (response) => {
      answered = true;
      return JSON.parse(await response.text());
    });
    const derivations = path.join(home, "data/cache/derivations");
    const persisted = () => (existsSync(derivations) ? readdirSync(derivations) : []);
    // Stage 0 is truly suspended: only the prompt is known, the worker has not run.
    let paused = await pausedTurn();
    assert.deepEqual([paused.stage, paused.stages, paused.step, paused.method], [0, 1, "impulse", ""]);
    assert.equal(solves, 0, "the worker has not solved the held turn");
    const first = await debug("advance", { token: TOKEN, turn: paused.turn, stage: 0 });
    assert.equal(first.status, 200);
    assert.equal((await debug("advance", { token: TOKEN, turn: paused.turn, stage: 0 })).status, 409);
    // Stages 1.. are revealed from the solved turn, held before it is persisted.
    paused = await pausedTurn();
    assert.equal(solves, 1, "the advance let the worker solve");
    const total = paused.stages;
    assert.equal(total, TWO_PLUS_TWO.length);
    assert.equal(paused.method, "arithmetic", "the route resolves through the method registry");
    assert.equal(paused.method_rust_source, "rust/src/solver_dispatch.rs:handle_arithmetic");
    assert.equal(paused.method_js_source, "js/worker/formal_ai_worker_arithmetic_and_numeric_lists.js:tryArithmetic");
    for (let stage = 1; stage < total; stage += 1) {
      assert.equal(paused.stage, stage);
      assert.equal(answered, false, `held before stage ${stage} is advanced`);
      assert.deepEqual(persisted(), [], `no derivation record is persisted while stage ${stage} is held`);
      assert.ok(paused.mermaid.endsWith(`\n    class s${stage} current`), `stage ${stage} is highlighted`);
      const advanced = await debug("advance", { token: TOKEN, turn: paused.turn, stage });
      assert.equal(advanced.status, 200);
      const repeated = await debug("advance", { token: TOKEN, turn: paused.turn, stage });
      assert.equal(repeated.status, 409, "a repeated advance never records a stage twice");
      assert.equal(repeated.body.error.message, "debug_stage_not_paused");
      if (stage + 1 < total) paused = advanced.body.paused[0];
    }
    const completion = await pending;
    ctx.worker.solve = solve;
    assert.match(completion.choices[0].message.content, /4/);
    assert.deepEqual(persisted(), [`${answerDerivationId(completion.choices[0].message.content)}.lino`],
      "the release persists the turn's derivation record");
    const events = (await debug("session", { token: TOKEN, since: before })).body.events;
    const advanced = events.filter((event) => event.kind === "stage_advanced");
    assert.deepEqual(advanced.map((event) => event.stage), [...Array(total).keys()]);
    assert.deepEqual(advanced.map((event) => event.stages), [1, ...Array(total - 1).fill(total)]);
    assertStageSources(advanced, TWO_PLUS_TWO);
    assert.deepEqual(advanced.slice(0, 2).map((event) => event.method), ["", "arithmetic"]);
    assert.equal(events.at(-1).kind, "turn_released");
    assert.equal(events.at(-1).reason, "completed");
  });

  test("a disconnected client and a release never leave a solve paused", async () => {
    await debug("pause", { token: TOKEN });
    const abort = new AbortController();
    const dropped = chat(abort.signal).catch((error) => error);
    await pausedTurn();
    abort.abort();
    await dropped;
    for (let attempt = 0; attempt < 100; attempt += 1) {
      const state = (await debug("session", { token: TOKEN })).body;
      if (!state.paused.length) break;
      await new Promise((resolve) => setTimeout(resolve, 20));
    }
    let state = (await debug("session", { token: TOKEN })).body;
    assert.deepEqual(state.paused, []);
    assert.equal(state.events.at(-1).reason, "disconnected");

    const pending = chat();
    await pausedTurn();
    state = (await debug("release", { token: TOKEN })).body;
    assert.equal(state.stepping, false);
    assert.deepEqual(state.paused, []);
    assert.equal(state.events.at(-1).reason, "released");
    assert.equal((await pending).status, 200);
  });
});


